355	/// Get all subtypes of a creature (from both card data and object-level subtypes).
356	fn get_subtypes(state: &GameState, creature_id: ObjectId, registry: &CardRegistry) -> Vec<String> {
357	    let mut subtypes = Vec::new();
358	    if let Some(obj) = state.get_object(creature_id) {
359	        subtypes.extend(obj.subtypes.iter().cloned());
360	        if let Some(data) = registry.card_data(obj.card_id) {
361	            for s in &data.subtypes {
362	                if !subtypes.contains(s) {
363	                    subtypes.push(s.clone());
364	                }
365	            }
366	        }
367	    }
368	    subtypes
369	}
