587	/// Get all creatures a player controls that are eligible to block.
588	/// Checks continuous effects (Pacifism, can't block, etc.).
589	pub fn eligible_blockers(state: &GameState, player: PlayerId, registry: &CardRegistry) -> Vec<ObjectId> {
590	    state.objects.values()
591	        .filter(|o| {
592	            o.zone == Zone::Battlefield
593	                && o.controller == player
594	                && o.power.is_some()
595	                && !o.tapped
596	        })
597	        .map(|o| o.id)
598	        .collect::<Vec<_>>()
599	        .into_iter()
600	        .filter(|&id| state.can_block(id, registry))
601	        // "Can't block" (e.g., Vampire Interloper) — check continuous effects.
602	        .filter(|&id| {
603	            !state.has_continuous_effect(id, &|e| {
604	                match e {
605	                    crate::types::ContinuousEffect::PreventBlock { scope } => Some(scope),
606	                    _ => None,
607	                }
608	            }, registry)
609	        })
610	        // "Can't block this turn" (e.g., Nightbird's Clutches).
611	        .filter(|&id| !state.until_end_of_turn_cant_block.contains(&id))
612	        .collect()
613	}
