225	        let pw_zero_loyalty_registry: Vec<_> = if let Some(reg) = registry {
226	            state.objects.values()
227	                .filter(|o| {
228	                    o.zone == Zone::Battlefield
229	                        && !o.card_types.contains(&crate::types::CardType::Planeswalker)
230	                        && reg.card_data(o.card_id)
231	                            .map(|d| d.card_types.contains(&crate::types::CardType::Planeswalker))
232	                            .unwrap_or(false)
233	                        && *o.counters.get(&crate::types::CounterType::Loyalty).unwrap_or(&0) == 0
234	                })
235	                .map(|o| o.id)
236	                .collect()
237	        } else {
238	            vec![]
239	        };
240	        for id in pw_zero_loyalty.into_iter().chain(pw_zero_loyalty_registry) {
241	            state.log(LogLevel::Event, format!("{} has 0 loyalty and is put into graveyard",
242	                state.get_object(id).map(|o| o.name.as_str()).unwrap_or("?")));
243	            state.move_object(id, Zone::Graveyard);
244	            took_action = true;
245	        }
