247	        // State-triggered abilities (CR 603.8): checked during SBA processing.
248	        // When the condition is met and the trigger is not already on the stack,
249	        // push a trigger onto pending_triggers so it goes on the stack and can
250	        // be responded to. The trigger won't fire again while it's on the stack.
251	        if let Some(reg) = registry {
252	            let garruk_card_id = reg.get_id_by_name("Garruk Relentless");
253	            if let Some(gid) = garruk_card_id {
254	                let garruk_to_trigger: Vec<_> = state.objects.values()
255	                    .filter(|o| {
256	                        o.zone == Zone::Battlefield
257	                            && o.card_id == gid
258	                            && !o.is_transformed
259	                            && !o.state_trigger_on_stack
260	                            && *o.counters.get(&crate::types::CounterType::Loyalty).unwrap_or(&0) <= 2
261	                    })
262	                    .map(|o| (o.id, o.controller))
263	                    .collect();
264	                for (id, controller) in garruk_to_trigger {
265	                    if let Some(obj) = state.get_object_mut(id) {
266	                        obj.state_trigger_on_stack = true;
267	                    }
268	                    state.pending_triggers.push(
269	                        crate::triggers::PendingTrigger::StateTriggered {
270	                            object_id: id,
271	                            card_id: gid,
272	                            controller,
273	                            description: "When Garruk Relentless has two or fewer loyalty counters on him, transform him".into(),
274	                        }
275	                    );
276	                    state.log(LogLevel::Event,
277	                        "Garruk Relentless's state-triggered ability triggers (transform)".into());
278	                    took_action = true;
279	                }
280	            }
281	        }
282	
283	        // Rule 704.5k: Legend rule — if a player controls two or more legendary
284	        // permanents with the same name, all are put into the graveyard.
285	        // (Simplified: keep the newest, remove the rest.)
286	        {
287	            use std::collections::HashMap as Map;
288	            let mut legend_groups: Map<(crate::ids::PlayerId, String), Vec<crate::ids::ObjectId>> = Map::new();
289	            for obj in state.objects.values() {
290	                if obj.zone == Zone::Battlefield && obj.is_legendary {
291	                    legend_groups.entry((obj.controller, obj.name.clone()))
292	                        .or_default()
293	                        .push(obj.id);
294	                }
295	            }
296	            for (_, ids) in legend_groups {
297	                if ids.len() > 1 {
298	                    // Keep the first (oldest), remove the rest.
299	                    for &id in &ids[1..] {
300	                        state.move_object(id, Zone::Graveyard);
301	                        took_action = true;
302	                    }
303	                }
304	            }
305	        }
306	
307	        // Rule 704.5d: A token not on the battlefield ceases to exist.
308	        let dead_tokens: Vec<_> = state.objects.values()
309	            .filter(|o| o.is_token && o.zone != Zone::Battlefield)
310	            .map(|o| o.id)
311	            .collect();
312	        for id in dead_tokens {
313	            state.objects.remove(&id);
314	            took_action = true;
315	        }
316	
317	        // Check for game end: only one (or zero) players alive.
318	        let alive: Vec<_> = state.players.iter().filter(|p| !p.lost).collect();
319	        if alive.len() <= 1 && state.result.is_none() {
320	            let result = if alive.len() == 1 {
321	                GameResult::Winner(alive[0].id)
322	            } else {
323	                GameResult::Draw
324	            };
325	            state.events.push(GameEvent::GameEnded { result: result.clone() });
326	            state.result = Some(result);
327	            took_action = true;
328	        }
329	
330	        if !took_action {
331	            break;
332	        }
333	        any_action = true;
334	    }
335	
336	    any_action
337	}
